"""Browser-readable, self-contained version of the measurement-noise report."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'multiCAFE/target/intake-measurement-noise/noise.json').read_text(encoding='utf-8'))
VIS=Path('C:/Users/fred/.codex/visualizations/2026/10/31/01a19132-23ad-7752-bebf-1afce8ba8fde')
template=r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Intake measurement noise and illumination</title>
<style>
body{font:16px/1.55 system-ui,sans-serif;color:#222;background:#fff;margin:0}main{max-width:1120px;margin:auto;padding:28px}h1{font-size:25px;line-height:1.3}h2{font-size:20px;margin-top:30px}p{max-width:100ch}small,.caption{color:#555;font-size:13px}.note{background:#f3f5f7;padding:14px 18px;border-left:3px solid #517ca5}select{font:inherit;padding:5px 9px;margin:0 15px 0 8px}svg{display:block;width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:8px 10px;border-bottom:1px solid #ddd;text-align:right}th:first-child,td:first-child{text-align:left}th{background:#f3f5f7}summary{cursor:pointer;padding:12px 0;font-weight:600}.table{overflow-x:auto}label{display:inline-block;margin:8px 0}code{overflow-wrap:anywhere;font-size:12px}a{color:#245d95}@media print{select{border:0}main{padding:0}.note{background:none}}
</style><main>
<h1>Intake detection: illumination and measurement uncertainty</h1>
<p id="scope"></p>
<p><strong>Typical position scatter is approximately 0.29 pixel.</strong> The middle half of capillary estimates spans 0.25–0.33 pixel.</p>
<p class="note">This measures the complete image-and-tracking chain, including processing, illumination changes and residual movement. It does not isolate camera read noise. A quiet trace may still be consistently misplaced.</p>
<h2>Initial findings</h2>
<p>In experiment 023, the outer traces 0L and 9R are darker: median brightness 102 and 115 digital levels, versus 148 for 1L. Position scatter is 0.42 and 0.34 pixel, versus 0.21 pixel for 1L.</p>
<p>Across the 16 experiments, the darkest quarter is noisier than the brightest quarter in 10 experiments. The median within-experiment ratio is 1.07. This is a modest, inconsistent association; brightness alone does not predict measurement uncertainty.</p>
<p>For 023/1L, detrended consecutive-interval scatter is 0.25 pixel, substantially larger than the approximately 0.02-pixel local-evaporation adjustment discussed for an early one-minute interval. This capillary has only 34 selected quiet points, so its estimate is preliminary.</p>
<label>Experiment <select id="experiment"></select></label><label>Capillary <select id="capillary"></select></label>
<h2>Brightness across capillaries</h2><div id="brightness"></div>
<h2>Position scatter across capillaries</h2><div id="noise"></div>
<p class="caption">Accent circles: direct detrended estimate; grey ticks: difference-based estimate. Hollow circles identify no-fly controls. Capillary order follows exported names, 0L to 9R; correspondence to physical camera numbering is not independently established.</p>
<h2 id="traceTitle"></h2><div id="trace"></div><div class="table" id="metrics"></div>
<p class="caption">Grey trace: saved topraw. Accent dots: points used for estimation. Image rows increase downward. The difference estimate divides robust increment scatter by √2 and assumes independent position errors. Correlation and fitted trends can invalidate that interpretation; the direct estimate is shown alongside it.</p>
<h2>Estimate sensitivity</h2><div class="table" id="sensitivity"></div>
<details><summary>All capillaries in the selected experiment</summary><div class="table" id="allCaps"></div></details>
<h2>How the estimates were calculated</h2>
<ol><li>Use finite positions at least 10 rows from image borders. For fly capillaries, exclude automatic and edited positive bins, their positional endpoints, and two neighbouring columns on either side. Keep apparent intake events in no-fly controls so tracking failures remain represented.</li>
<li>Use contiguous stretches of at least eight points, split into blocks of at most 21. Fit a robust linear trend separately in each block to remove slow drift.</li>
<li>Calculate residual MAD × 1.4826, with an approximate correction for the two fitted trend parameters. Individual residual fluctuations are not clipped. Report increment fluctuations and lag-one correlation separately.</li>
<li>Compare with median digital RGB brightness within ±10 rows of topraw, and RMS RGB contrast between bands above and below it. These are processed-image descriptors, not calibrated irradiance measurements.</li></ol>
<p>Among 292 traces with at least 40 quiet points and three blocks, median position scatter is 0.30 pixel. Using shorter blocks of at most 15 points gives 0.28 pixel across the usable traces. Three traces have insufficient quiet data. Candidate quiet stretches in fly capillaries are not independently confirmed absence of feeding. Outer position and no-fly control status are confounded.</p>
<h2>Camera noise versus practical measurement uncertainty</h2>
<p>The current kymograph builder spatially averages camera pixels and can subsample source frames. Checked originals for experiment 023 are JPEGs about one minute apart; the inspected first frame contains no EXIF camera settings. These files cannot uniquely separate sensor noise, JPEG compression, light-panel variation, tracking and residual physical movement.</p>
<p>A separate camera characterization would use repeated images of a stationary scene at fixed exposure and gain, dark frames and several uniform illumination levels, preserving original pixel values and accounting for processing. See <a href="https://www.emva.org/standards-technology/emva-1288/">EMVA 1288</a>.</p>
<p><strong>No detector parameters or experimental data were changed.</strong> Record 25/370 onward will use Local evaporation off consistently. Earlier settings were not consistently monitored; exported metadata remains authoritative. This analysis detrends raw traces directly and does not subtract optional local evaporation.</p>
<details><summary>Sources and excluded version</summary><div id="sources"></div></details>
<noscript>This interactive report requires JavaScript enabled in your browser.</noscript>
</main><script>
const D=__DATA__;
const el=id=>document.getElementById(id), f=(v,n=2)=>v==null?'unavailable':Number(v).toLocaleString(undefined,{maximumFractionDigits:n});
const colors={accent:'#245d95',muted:'#888',grid:'#ddd',text:'#444'};
function options(node,items,value){node.replaceChildren();for(const item of items){const o=document.createElement('option');o.value=item.value;o.textContent=item.label;node.append(o);}if(items.some(o=>o.value===value))node.value=value;}
function table(id,headers,rows){const t=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');for(const h of headers){const th=document.createElement('th');th.textContent=h;tr.append(th);}head.append(tr);t.append(head);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(const v of row){const td=document.createElement('td');td.textContent=v;tr.append(td);}body.append(tr);}t.append(body);el(id).replaceChildren(t);}
function svgPlot(caps,metric){const W=940,H=265,L=65,R=20,T=20,B=46,bright=metric==='brightness',value=c=>bright?c.brightness.median:c.positionSigma;const max=bright?255:Math.max(.5,...caps.map(c=>value(c)||0))*1.15;const x=v=>L+(W-L-R)*v/19,y=v=>H-B-(H-T-B)*v/max;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${bright?'Brightness':'Position scatter'} by capillary">`;for(const q of [0,.25,.5,.75,1])svg+=`<line x1="${L}" x2="${W-R}" y1="${y(q*max)}" y2="${y(q*max)}" stroke="${colors.grid}"/><text x="${L-8}" y="${y(q*max)+4}" text-anchor="end" font-size="11" fill="${colors.text}">${f(q*max,bright?0:2)}</text>`;for(const c of caps){svg+=`<text x="${x(c.position)}" y="${H-25}" text-anchor="middle" font-size="10">${c.cap}</text>`;if(value(c)==null)continue;svg+=`<circle cx="${x(c.position)}" cy="${y(value(c))}" r="4.5" fill="${c.control?'white':colors.accent}" stroke="${colors.accent}" stroke-width="2"><title>${c.cap}: ${f(value(c),3)}; ${c.points} selected points</title></circle>`;if(!bright&&c.differenceSigma!=null)svg+=`<path d="M${x(c.position)-5},${y(c.differenceSigma)} h10" stroke="${colors.muted}" stroke-width="2"/>`;}svg+=`<text x="${W/2}" y="${H-4}" text-anchor="middle" font-size="12">Capillary in exported order</text><text x="16" y="${H/2}" transform="rotate(-90 16 ${H/2})" text-anchor="middle" font-size="12">${bright?'Digital RGB mean (0–255)':'Robust scatter (kymograph pixels)'}</text></svg><p class="caption">Source: experiment ${caps[0].experiment}, 0–${f(Math.max(...caps.map(c=>c.duration)))} min. ${bright?'Median brightness near topraw, selected quiet columns.':'Position estimates from locally detrended stretches.'}</p>`;el(bright?'brightness':'noise').innerHTML=svg;}
function trace(c){const W=940,H=270,L=65,R=20,T=20,B=46,s=c.series,lo=Math.min(...s.map(p=>p[1]))-1,hi=Math.max(...s.map(p=>p[1]))+1,last=s[s.length-1][0],x=v=>L+(W-L-R)*v/last,y=v=>T+(H-T-B)*(v-lo)/(hi-lo);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Saved topraw and samples selected for noise estimation">`;for(const q of [0,.5,1])svg+=`<line x1="${L}" x2="${W-R}" y1="${y(lo+q*(hi-lo))}" y2="${y(lo+q*(hi-lo))}" stroke="${colors.grid}"/><text x="${L-8}" y="${y(lo+q*(hi-lo))+4}" text-anchor="end" font-size="11">${f(lo+q*(hi-lo),1)}</text>`;svg+=`<path d="${s.map((p,i)=>`${i?'L':'M'}${x(p[0])},${y(p[1])}`).join(' ')}" fill="none" stroke="${colors.muted}" stroke-width="1.3"/>`;for(const p of s.filter(p=>p[2]))svg+=`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="2.4" fill="${colors.accent}"/>`;for(const q of [0,.25,.5,.75,1])svg+=`<text x="${x(q*last)}" y="${H-24}" text-anchor="middle" font-size="11">${f(q*last,1)}</text>`;svg+=`<text x="${W/2}" y="${H-4}" text-anchor="middle" font-size="12">Elapsed time (min)</text><text x="16" y="${H/2}" transform="rotate(-90 16 ${H/2})" text-anchor="middle" font-size="12">Saved topraw row (px; down)</text></svg>`;el('trace').innerHTML=svg;el('traceTitle').textContent=`Selected samples: ${c.experiment}/${c.cap}`;}
function render(){const caps=D.capillaries.filter(c=>c.experiment===el('experiment').value).sort((a,b)=>a.position-b.position);const c=caps.find(c=>c.cap===el('capillary').value)||caps[0];svgPlot(caps,'brightness');svgPlot(caps,'noise');trace(c);table('metrics',['Capillary','Quiet points / blocks','Position scatter (px)','Difference estimate (px)','95th percentile increment fluctuation (px)','Lag-one correlation'],[[c.cap,`${c.points} / ${c.blocks.length}`,f(c.positionSigma,3),f(c.differenceSigma,3),f(c.incrementAbsP95,3),f(c.residualLag1)]]);table('sensitivity',['Selection and detrending','Points','Position scatter (px)'],[['Main: 2-bin guard, up to 21 points',c.points,f(c.positionSigma,3)],...c.sensitivity.map(s=>[`${s.guard}-bin guard, up to ${s.block} points`,s.points,f(s.positionSigma,3)]),['Reliable-flag points only',c.reliableOnly.points,f(c.reliableOnly.positionSigma,3)]]);table('allCaps',['Capillary','Role','Brightness (0–255)','RGB contrast','Position scatter (px)','Quiet points','Coverage'],caps.map(c=>[c.cap,c.control?'No-fly control':'Fly',f(c.brightness.median,1),f(c.contrast.median,1),f(c.positionSigma,3),c.points,c.positionSigma==null?'Insufficient stretches':c.points>=40&&c.blocks.length>=3?'At least 40 points / 3 blocks':'Limited; preliminary']));}
function selectExperiment(){const caps=D.capillaries.filter(c=>c.experiment===el('experiment').value).sort((a,b)=>a.position-b.position);options(el('capillary'),caps.map(c=>({value:c.cap,label:c.cap+(c.control?' (control)':'')})),el('capillary').value);render();}
options(el('experiment'),D.experiments.map(e=>({value:e.id,label:`${e.id} (${e.usable}/${e.caps} estimates)`})),'023');el('experiment').addEventListener('change',selectExperiment);el('capillary').addEventListener('change',render);el('scope').textContent=`${D.summary.experiments} experiments · ${D.summary.caps} traces · ${D.summary.usable} estimates · approximately one-minute native intervals`;for(const s of D.sources){const p=document.createElement('p');p.textContent=`${s.id}: ${s.file}. SHA-256: ${s.sha256}`;el('sources').append(p);}for(const s of D.excludedSources){const p=document.createElement('p');p.textContent=`Excluded ${s.id}: ${s.reason}`;el('sources').append(p);}selectExperiment();
</script></html>'''
target=VIS/'intake-measurement-noise.html'
target.write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')),encoding='utf-8')
print(target)
